const input = $input.first().json;

if (input.isRetry) {
  const userPrompt = `The project you generated previously failed its tests. Here is what you generated:

${input.filesJsonRaw}

Here is the test/install output (stdout+stderr, truncated):

${input.output}

Fix the code so \`npm install && npm test\` succeeds. Return the COMPLETE corrected file set using the same JSON schema as before (the full "files" array, not a diff) - strictly JSON, no markdown fences, no commentary.`;

  return [{
    json: {
      systemPrompt: input.systemPrompt,
      userPrompt,
      outputDir: input.outputDir,
      retryCount: input.retryCount,
      maxRetries: input.maxRetries,
      originalPrompt: input.originalPrompt
    }
  }];
}

const body = input.body || input;
if (!body.prompt) {
  throw new Error('Request body must include a "prompt" field describing the app to generate.');
}

const targetType = body.target === 'frontend'
  ? 'frontend (React, single-page app)'
  : 'backend (Node.js + Express REST API)';

const outputDir = (body.outputDir || 'generated-app').replace(/[^a-zA-Z0-9_-]/g, '-');
const maxRetries = Number.isInteger(body.maxRetries) ? body.maxRetries : 3;

const systemPrompt = `You are a code generator. Given a plain-language description of an app, output a complete, runnable ${targetType} project as STRICT JSON only, matching exactly this schema and nothing else (no markdown fences, no commentary, no text before or after the JSON):

{"files":[{"path":"relative/file/path.ext","content":"full file contents as a string"}]}

Rules:
- MUST include a package.json with a "test" script that runs deterministically with no network access beyond npm install, and exits non-zero with a clear error message on failure, 0 on success.
- For a backend project, package.json MUST also include a "start" script that boots the server, and the server MUST listen on process.env.PORT (falling back to 3000 if unset) — this is required for automated deployment.
- For a frontend project, the "test" script may just be a build/typecheck step (e.g. "tsc --noEmit") if full component tests aren't practical without a browser.
- Include every file needed to install, run, and test the project.
- Keep the project minimal but functional.
- Do not include node_modules, .git, or any build output.
- All "path" values must be relative (no leading slash, no "..").
- Respond with the JSON object only.`;

return [{
  json: {
    systemPrompt,
    userPrompt: body.prompt,
    outputDir,
    retryCount: 0,
    maxRetries
  }
}];

const response = $input.first().json;
const text = (response.content && response.content[0] && response.content[0].text) || '';

let parsed;
try {
  parsed = JSON.parse(text);
} catch (e) {
  throw new Error('Claude did not return valid JSON. Raw response (truncated): ' + text.slice(0, 500));
}

if (!parsed.files || !Array.isArray(parsed.files)) {
  throw new Error('Expected a "files" array in the generated JSON but did not find one.');
}

const prior = $('Prepare Prompt').itemMatching(0).json;
const outputDir = prior.outputDir;
const baseDir = '/home/node/generated/' + outputDir;

const safePathRe = /^[A-Za-z0-9_][A-Za-z0-9_.\-\/]*$/;
const lines = ['set -e'];
const fileList = [];

for (const f of parsed.files) {
  if (!f.path || !safePathRe.test(f.path) || f.path.indexOf('..') !== -1) {
    throw new Error('Unsafe or invalid file path from generated output: ' + JSON.stringify(f.path));
  }
  const fullPath = baseDir + '/' + f.path;
  const b64 = Buffer.from(String(f.content == null ? '' : f.content), 'utf8').toString('base64');
  lines.push('mkdir -p "$(dirname "' + fullPath + '")"');
  lines.push("printf '%s' '" + b64 + "' | base64 -d > \"" + fullPath + "\"");
  fileList.push(f.path);
}

lines.push('cd "' + baseDir + '"');
lines.push('npm install --no-audit --no-fund');
lines.push('npm test');

return [{
  json: {
    command: lines.join('\n'),
    outputDir,
    retryCount: prior.retryCount,
    maxRetries: prior.maxRetries,
    originalPrompt: prior.originalPrompt,
    systemPrompt: prior.systemPrompt,
    fileList,
    filesJsonRaw: text
  }
}];

const testResult = $input.first().json;
const prior = $('Build Script').itemMatching(0).json;

const exitCode = typeof testResult.exitCode === 'number' ? testResult.exitCode : 1;
const passed = exitCode === 0;
const output = ((testResult.stdout || '') + '\n' + (testResult.stderr || '')).slice(-4000);

return [{
  json: {
    passed,
    exitCode,
    output,
    outputDir: prior.outputDir,
    retryCount: prior.retryCount,
    maxRetries: prior.maxRetries,
    originalPrompt: prior.originalPrompt,
    systemPrompt: prior.systemPrompt,
    fileList: prior.fileList,
    filesJsonRaw: prior.filesJsonRaw
  }
}];

const d = $input.first().json;
return [{
  json: {
    status: 'ok',
    outputDir: d.outputDir,
    retriesUsed: d.retryCount,
    filesWritten: (d.fileList || []).length,
    files: d.fileList || [],
    testOutput: d.output
  }
}];

const prior = $input.first().json;
return [{
  json: {
    isRetry: true,
    retryCount: prior.retryCount + 1,
    maxRetries: prior.maxRetries,
    outputDir: prior.outputDir,
    originalPrompt: prior.originalPrompt,
    systemPrompt: prior.systemPrompt,
    filesJsonRaw: prior.filesJsonRaw,
    output: prior.output
  }
}];

const d = $input.first().json;
return [{
  json: {
    status: 'failed',
    reason: 'Max retries exceeded - tests still failing.',
    outputDir: d.outputDir,
    retriesUsed: d.retryCount,
    lastTestOutput: d.output
  }
}];
